window.KATALCODE_SOURCES = {
  "contests/leetcode/weekly/524/Q2-last-visited-cell/solution.py": "\"\"\"LeetCode 4084: Last Visited Cell in a Directional Grid.\"\"\"\n\n\nclass Solution:\n    \"\"\"Simulate the path until the next move is invalid.\"\"\"\n\n    def lastVisitedCell(self, grid: list[list[str]]) -> list[int]:\n        rows, cols = len(grid), len(grid[0])\n        directions = {\n            \"L\": (0, -1),\n            \"R\": (0, 1),\n            \"U\": (-1, 0),\n            \"D\": (1, 0),\n        }\n        visited = [[False] * cols for _ in range(rows)]\n        row = col = 0\n\n        while True:\n            visited[row][col] = True\n            delta_row, delta_col = directions[grid[row][col]]\n            next_row = row + delta_row\n            next_col = col + delta_col\n\n            if not (0 <= next_row < rows and 0 <= next_col < cols):\n                return [row, col]\n            if visited[next_row][next_col]:\n                return [row, col]\n\n            row, col = next_row, next_col\n",
  "contests/leetcode/weekly/524/Q3-colored-tree-root/solution.py": "\"\"\"O(n) solution for LeetCode 4085: Find Root of a Colored Tree.\"\"\"\n\n\nCOLOR_AFTER = {\"R\": \"B\", \"B\": \"W\", \"W\": \"R\"}\n\n\ndef find_colored_root(edges: list[list[int]], colors: str) -> int:\n    \"\"\"Orient color-compatible edges and return the unique indegree-zero node.\"\"\"\n    node_count = len(colors)\n    indegree = [0] * node_count\n    degree = [0] * node_count\n\n    for first, second in edges:\n        degree[first] += 1\n        degree[second] += 1\n\n        if COLOR_AFTER[colors[first]] == colors[second]:\n            indegree[second] += 1\n        elif COLOR_AFTER[colors[second]] == colors[first]:\n            indegree[first] += 1\n        else:\n            # Equal-colored endpoints can never occupy adjacent depths.\n            return -1\n\n    roots = [node for node, incoming in enumerate(indegree) if incoming == 0]\n    if len(roots) != 1:\n        return -1\n\n    root = roots[0]\n    if degree[root] > 2:\n        return -1\n    if any(indegree[node] != 1 for node in range(node_count) if node != root):\n        return -1\n\n    return root\n\n\nclass Solution:\n    \"\"\"LeetCode-compatible entry point.\"\"\"\n\n    def findColoredRoot(self, edges: list[list[int]], colors: str) -> int:\n        return find_colored_root(edges, colors)\n"
};
